INSERT INTO `granite_products` VALUES (1,'DIAMOND WHITE','หินแกรนิตไดมอนด์ไวท์ (ชนิดโดโลไมต์) DIAMOND WHITE',3590.00,'https://media.siamtak.com/24dd12385361-WDM.jpg','https://www.siamtak.com/products/diamond-white','white','marble','[\"Classic\", \"Minimal\"]','[\"counter\", \"wall\", \"floor\"]','indoor','{\"price\": 1, \"luxury\": 3, \"modern\": 4, \"durability\": 4, \"maintenance\": 3}','2026-09-21 05:04:50','2026-10-08 09:24:31');
INSERT INTO `granite_products` VALUES (2,'JASPER RED','หินอ่อนแจสเปอร์ เรด (Jasper Red Marble) หินอ่อนนำเข้าสีแดงเข้ม โดดเด่นด้วยลวดลายเส้นแร่สีขาวที่แทรกตัวอยู่ทั่วแผ่นหิน ให้ความรู้สึกแข็งแกร่งและหรูหราในเวลาเดียวกัน เป็นหินที่นิยมใช้ในการตกแต่งเพื่อสร้างจุดเด่นให้กับพื้นที่ห้องรับแขก, ท็อปเคาน์เตอร์บาร์สุดหรู, หรือโต๊ะรับประทานอาหารที่ต้องการความโดดเด่นไม่ซ้ำใคร',2290.00,'https://media.siamtak.com/06770aff698f-JPR-RE.jpg','https://www.siamtak.com/products/jasper-red','red','marble','[\"Luxury\"]','[\"livingroom\", \"counter\", \"table\"]','indoor','{\"price\": 3, \"luxury\": 5, \"modern\": 3, \"durability\": 4, \"maintenance\": 3}','2026-09-21 05:04:50','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (3,'SILVER OROBICO','หินอ่อนซิลเวอร์โอโลบิโก้ (Silver Orobico Marble) ความงามที่เกิดจากชั้นหินนับพันปี ถ่ายทอดออกมาเป็นลวดลายเส้นแร่ที่ซ้อนทับและไหลราวกับศิลปะธรรมชาติบนผืนผ้าใบ สีเทาน้ำตาลผสานกับเส้นแร่สีขาวและประกายแร่แฝง สร้างเอกลักษณ์ที่ไม่ซ้ำแบบใคร มอบบรรยากาศที่ทรงพลังและเปี่ยมด้วยรสนิยม',4390.00,'https://media.siamtak.com/6da5003ae8c1-SOB-Cover.jpg','https://www.siamtak.com/products/silver-orobico','grey','marble','[\"Luxury\"]','[\"counter\", \"wall\", \"table\"]','indoor','{\"price\": 1, \"luxury\": 5, \"modern\": 3, \"durability\": 4, \"maintenance\": 3}','2026-09-21 05:04:50','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (4,'BRECCIA DAMASCATA','หินอ่อนเบรคเซีย ดามาสกาต้า (Breccia Damascata Marble) เนื้อหินโทนสีแดงอิฐสลับกับลวดลายเส้นแร่สีขาวและสีน้ำตาลเข้มอันเป็นเอกลักษณ์ ช่วยเติมเต็มความโดดเด่นและเพิ่มความอบอุ่นที่ดูหรูหราให้กับพื้นที่ของคุณ อย่างเช่นการติดตั้งเป็นผนังตกแต่ง หรือท็อปโต๊ะอาหาร สามารถตกแต่งได้หลากหลายสไตล์',2590.00,'https://media.siamtak.com/0f3b83ce36ba-DMT-LOW.jpg','https://www.siamtak.com/products/breccia-damascata','red','marble','[\"Luxury\", \"Classic\"]','[\"wall\", \"table\"]','indoor','{\"price\": 2, \"luxury\": 5, \"modern\": 3, \"durability\": 4, \"maintenance\": 3}','2026-09-21 05:04:51','2026-10-08 09:24:31');
INSERT INTO `granite_products` VALUES (5,'ROSSO OROBICO','หินอ่อนรอสโซ่โอโรบิโก (Rosso Orobico Marble) หนึ่งในหินอ่อนที่มีเอกลักษณ์เฉพาะตัวจากประเทศอิตาลี โดดเด่นด้วยลวดลายที่งดงามเสมือนงานศิลป์ตามธรรมชาติ พื้นหินมีโทนสีเทาอ่อนผสมผสานกับเส้นสายลวดลายสีขาว ขับเน้นด้วยแถบเส้นสีน้ำตาล ทอง และแดงที่พาดผ่านอย่างพลิ้วไหว คล้ายภาพวาดแนว Abstract ที่ธรรมชาติรังสรรค์ขึ้น ทำให้ทุกแผ่นหินแตกต่างไม่ซ้ำกัน',3690.00,'https://media.siamtak.com/26de0b4dace3-66a0c1e2611080d7d046d9ea_ATC-670305-2-cover.jpg','https://www.siamtak.com/products/rosso-orobico','grey','marble','[\"Luxury\"]','[\"wall\", \"counter\"]','indoor','{\"price\": 1, \"luxury\": 5, \"modern\": 3, \"durability\": 4, \"maintenance\": 3}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (6,'CLASSICAL WHITE','หินแกรนิต คลาสสิกคอลไวท์ (Classical White Granite) เติมเต็มพื้นที่ของคุณด้วยความบริสุทธิ์และเรียบง่ายของหินแกรนิต Classical White ลวดลายเส้นสายสีเทาอ่อนพาดผ่านพื้นผิวสีขาวนวลอย่างเป็นธรรมชาติ มอบความรู้สึกสะอาดตาและทันสมัย สามารถเข้าได้กับทุกสไตล์การออกแบบ ไม่ว่าจะเป็นเคาน์เตอร์ครัวหรือผนังตกแต่ง',1790.00,'https://media.siamtak.com/303821e04f3a-654b3e125d72664d765babd0_CS1.jpg','https://www.siamtak.com/products/classic-white','white','granite','[\"Classic\", \"Modern\"]','[\"kitchen\", \"counter\", \"wall\"]','indoor','{\"price\": 3, \"luxury\": 3, \"modern\": 5, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (7,'BLUE PEARL #2','หินแกรนิต บลูเพิร์ล #2 (Blue Pearl #2) ด้วยเฉดฟ้าเข้มที่ลุ่มลึกและลวดลายละเอียด หินแกรนิตบลูเพิร์ล #2 ให้ความรู้สึกสงบหรูหรา เหมาะอย่างยิ่งสำหรับพื้นที่ที่เน้นดีไซน์เรียบง่ายแต่พรีเมียม เช่น เคาน์เตอร์บาร์ โต๊ะกลาง หรือพื้นห้องรับแขก ช่วยเพิ่มมิติที่ดูมีระดับโดยไม่ฉูดฉาดเกินไป',2490.00,'https://media.siamtak.com/64fa0705a1ed-65447e1a785455814ce909df_BP02.jpg','https://www.siamtak.com/products/blue-pearl-2','blue','granite','[\"Luxury\", \"Minimal\"]','[\"counter\", \"table\", \"floor\", \"livingroom\"]','indoor','{\"price\": 3, \"luxury\": 5, \"modern\": 4, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (8,'AFRICAN BLACK','หินแกรนิตดำแอฟริกา (African Black Granite) หินแกรนิตสีดำที่มีคุณภาพสูงที่สุดและดำสนิทที่สุด เหมาะสำหรับนำไปทำเป็นท็อปครัว ท็อปโต๊ะ หรือจุดต่าง ๆ ที่ต้องการความแข็งแรง',2190.00,'https://media.siamtak.com/da2bfe23060e-6544835929006ff12c703584_AB.jpeg','https://www.siamtak.com/products/african-black','black','granite','[\"Modern\"]','[\"kitchen\", \"counter\", \"table\"]','indoor','{\"price\": 3, \"luxury\": 3, \"modern\": 5, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (9,'RIVER GOLD','หินแกรนิตริเวอร์โกล์ด (River Gold Granite) นิยามของความหรูหราที่มาพร้อมความงามตามธรรมชาติ ด้วยพื้นผิวสีครีมและทองอร่ามที่สอดแทรกด้วยลวดลายเส้นสายสีน้ำตาลเข้มและสีดำ ทำให้ดูมีมิติและเคลื่อนไหวคล้ายผืนน้ำในแม่น้ำที่ระยิบระยับ หินแกรนิตชนิดนี้ไม่เพียงแต่ให้ความรู้สึกอบอุ่นและโอ่อ่า แต่ยังมีคุณสมบัติที่แข็งแกร่งทนทานต่อการใช้งานหนัก เหมาะอย่างยิ่งสำหรับการทำเคาน์เตอร์ในครัว พื้น หรือผนังที่ต้องการวัสดุที่สวยงามและใช้งานได้จริงในระยะยาว',1990.00,'https://media.siamtak.com/9a32715c96f5-67ca77148702b909d767fc33_RVG-Low.jpg','https://www.siamtak.com/products/river-gold','brown','granite','[\"Luxury\", \"Classic\"]','[\"kitchen\", \"counter\", \"floor\", \"wall\"]','indoor','{\"price\": 3, \"luxury\": 5, \"modern\": 3, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (10,'BIANCO BLACK','หินแกรนิตเบียงโก้แบล็ค (Bianco Black Granite) ประกายเกล็ดแร่สีทองสุดสวยงามเมื่อมีแสงมากระทบที่หน้าหิน หินแกรนิตดำเกล็ดทองที่ขึ้นชื่อเรื่องความงามเหนือกาลเวลา พื้นหินสีดำสนิทแทรกด้วยประกายเกล็ดแร่ทองที่ระยิบระยับเมื่อสะท้อนกับแสง ช่วยเพิ่มมิติและความหรูหราให้ทุกพื้นที่ เหมาะสำหรับงานตกแต่งหลากหลาย ไม่ว่าจะเป็นพื้น เคาน์เตอร์ครัว หรือผนังตกแต่งที่ต้องการความพิเศษ',1790.00,'https://media.siamtak.com/b6641493f986-67ca9788fa6814c0fe9c7394_BB-cover.jpg','https://www.siamtak.com/products/bianco-black','black','granite','[\"Luxury\"]','[\"floor\", \"kitchen\", \"counter\", \"wall\"]','indoor','{\"price\": 3, \"luxury\": 5, \"modern\": 3, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (11,'RIVER WHITE','หินแกรนิตริเวอร์ไวท์ (River White Granite) โดดเด่นด้วยพื้นผิวสีขาวนวลสะอาดตาที่มีลายเส้นสีเทาเข้มพาดผ่านราวกับสายน้ำที่ไหลอย่างสงบงาม เส้นสายที่พลิ้วไหวนี้สร้างความรู้สึกที่อ่อนโยนและเป็นธรรมชาติ ทำให้เป็นหินที่เหมาะกับการตกแต่งในทุกสไตล์ ไม่ว่าจะเป็นเคาน์เตอร์ในครัวที่ต้องการความสว่าง หรือผนังที่ต้องการความเรียบง่ายแต่มีเอกลักษณ์',1790.00,'https://media.siamtak.com/791f813c6c06-654b4644080dce0d6c1e06e5_RVW.jpg','https://www.siamtak.com/products/river-white','white','granite','[\"Modern\", \"Minimal\"]','[\"kitchen\", \"counter\", \"wall\"]','indoor','{\"price\": 3, \"luxury\": 3, \"modern\": 5, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (12,'VISCON WHITE','หินแกรนิต วิสคอนไวท์ (Viscon White Granite) เผยความสง่างามในทุกมุมมอง ด้วยพื้นสีขาวสะอาดสอดแทรกลวดลายเทาอ่อนแบบธรรมชาติ ให้ความรู้สึกกว้าง โปร่ง และเรียบหรู เหมาะสำหรับพื้นที่ที่ต้องการแสงสะท้อนและบรรยากาศสบายตา ไม่ว่าจะเป็นพื้น เคาน์เตอร์ หรือผนังตกแต่ง ทำให้ทุกพื้นที่ดูมีชีวิตชีวาและคลาสสิกในเวลาเดียวกัน',1590.00,'https://media.siamtak.com/9d65d4fc17c9-67eba81fcce31211c8c9c460_VGW.jpg','https://www.siamtak.com/products/viscon-white','white','granite','[\"Modern\", \"Classic\"]','[\"floor\", \"counter\", \"wall\"]','indoor','{\"price\": 3, \"luxury\": 3, \"modern\": 5, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (13,'BLACK FOREST','หินแกรนิต แบล็คฟอเรสท์ (Black Forest) นำความสง่างามจากธรรมชาติมาสู่การตกแต่งของคุณอย่างแท้จริง ด้วยพื้นผิวสีดำเข้มที่ดูทรงพลัง ตัดกับลายเส้นสีขาวที่พลิ้วไหวราวกับภาพวาดพู่กันจีน ทำให้แต่ละแผ่นมีเอกลักษณ์เฉพาะตัวไม่ซ้ำกัน หินชนิดนี้ให้ความรู้สึกแข็งแกร่งและน่าค้นหา เหมาะสำหรับพื้นที่ที่ต้องการความโดดเด่นและมีสไตล์ที่แตกต่างอย่างมีระดับ',1890.00,'https://media.siamtak.com/e8b4c1a78b1c-65448225524e34d59f4a4a1e_BFS.jpeg','https://www.siamtak.com/products/black-forest','black','granite','[\"Luxury\"]','[\"counter\", \"wall\", \"floor\"]','indoor','{\"price\": 3, \"luxury\": 5, \"modern\": 3, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (14,'LEMURIAN BLUE','หินแกรนิตลีมูเรียนบลู (Lemurian Blue Granite) หินแกรนิตระดับพรีเมียมที่โดดเด่นด้วยเฉดสีน้ำเงินเข้มสลับประกายฟ้าและเขียวราวกับแสงเหนือ ทำให้พื้นผิวดูมีชีวิตชีวาและหรูหราไม่เหมือนใคร ลายธรรมชาติที่ซับซ้อนและประกายระยิบระยับของ Lemurian Blue สะท้อนถึงความงดงามอันล้ำค่าจากใต้พิภพ เหมาะอย่างยิ่งสำหรับงานตกแต่งที่ต้องการความโดดเด่น เช่น เคาน์เตอร์ครัว ไอส์แลนด์ แผงผนัง และโต๊ะกลาง หินชนิดนี้ไม่เพียงเพิ่มความงามให้พื้นที่ แต่ยังมีความแข็งแรง ทำให้ใช้งานได้จริงควบคู่กับความงดงามเหนือกาลเวลา Lemurian Blue จึงเป็นตัวเลือกที่ตอบโจทย์ทั้งฟังก์ชันและดีไซน์ระดับหรู',4990.00,'https://media.siamtak.com/7e0e73c71979-67ca822843c254bc2cfbd64c_LRB-cover.jpg','https://www.siamtak.com/products/lemurian-blue','blue','granite','[\"Luxury\"]','[\"kitchen\", \"counter\", \"wall\", \"table\"]','indoor','{\"price\": 1, \"luxury\": 5, \"modern\": 3, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (15,'MONALISA','หินแกรนิตโมนาริซา (Monalisa Marble) เป็นตัวแทนของความสง่างามเหนือกาลเวลา โทนสีเทาอ่อนผสานลายเส้นแร่ที่ละเอียดอ่อน เหมือนผลงานศิลปะบนพื้นผิวหิน สร้างบรรยากาศหรูหราแต่ไม่โอ้อวด เหมาะสำหรับงานตกแต่งภายในที่ต้องการความละเอียดอ่อนและความประณีต เช่น เคาน์เตอร์บาร์, ผนังโชว์ หรือพื้นห้องรับแขก',2190.00,'https://media.siamtak.com/a2663ba0ebe9-6735954d26620adac55d0d0f_MNL.jpg','https://www.siamtak.com/products/monalisa','grey','marble','[\"Luxury\", \"Classic\"]','[\"counter\", \"wall\", \"floor\", \"livingroom\"]','indoor','{\"price\": 3, \"luxury\": 5, \"modern\": 3, \"durability\": 4, \"maintenance\": 3}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (16,'EMERALD PEARL','หินแกรนิต เอ็มเมอรัลเพิร์ล (Emerald Pearl Granite) มีความพิเศษอยู่ที่สีเขียวอมดำที่ดูหรูหราลุ่มลึก พร้อมประกายมุกสีทองและเงินที่แวววาวเมื่อต้องแสงไฟ ทำให้ดูงดงามและลึกลับราวกับอัญมณีล้ำค่า เป็นตัวเลือกที่ยอดเยี่ยมสำหรับงานที่ต้องการความหรูหราและดึงดูดสายตา เช่น เคาน์เตอร์ครัวหรือผนังตกแต่งในห้องน้ำ',3479.00,'https://media.siamtak.com/3100856b2bc7-65447c9d93ead1c038ae5736_EP.jpeg','https://www.siamtak.com/products/emerald-pearl','green','granite','[\"Luxury\"]','[\"kitchen\", \"counter\", \"bathroom\", \"wall\"]','indoor','{\"price\": 2, \"luxury\": 5, \"modern\": 3, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (17,'BLACK GALAXY','หินแกรนิตดำเกล็ดทอง (Black Galaxy Granite) หินแกรนิตสีดำที่มีประกายเกล็ดแร่สีทองสุดสวยงามเมื่อมีแสงมากระทบที่หน้าหินทำให้มีประกายเกล็ดแร่สีทองสุดสวยงามเมื่อมีแสงมากระทบที่หน้าหิน หินแกรนิตดำเกล็ดทองที่ขึ้นชื่อเรื่องความงามเหนือกาลเวลา พื้นหินสีดำสนิทแทรกด้วยประกายเกล็ดแร่ทองที่ระยิบระยับเมื่อสะท้อนกับแสง ช่วยเพิ่มมิติและความหรูหราให้ทุกพื้นที่ เหมาะสำหรับงานตกแต่งหลากหลาย ไม่ว่าจะเป็นพื้น เคาน์เตอร์ครัว หรือผนังตกแต่งที่ต้องการความพิเศษ',1990.00,'https://media.siamtak.com/a1bd3a3cf0bb-6555c70232fd5d4c898f0c82_GDP.jpg','https://www.siamtak.com/products/black-galaxy','black','granite','[\"Luxury\", \"Modern\"]','[\"floor\", \"kitchen\", \"counter\", \"wall\"]','indoor','{\"price\": 3, \"luxury\": 5, \"modern\": 5, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (18,'TITANIUM GOLD','หินแกรนิตไทเทเนียมโกลด์ (Titanium Gold Granite) โดดเด่นด้วยโทนสีดำเข้มตัดกับลายแร่ทองและขาวที่สวยสะดุดตา ให้ความรู้สึกหรูหราและทันสมัย เหมาะสำหรับงานตกแต่งที่ต้องการความพิเศษ เช่น เคาน์เตอร์ครัว เคาน์เตอร์บาร์ หรือผนังตกแต่ง ที่ต้องการสไตล์โดดเด่นและความทนทานสูง',3590.00,'https://media.siamtak.com/10c2df25987d-67ca9b0643631894fede769d_TTG.jpg','https://www.siamtak.com/products/titanium-gold','black','granite','[\"Luxury\", \"Modern\"]','[\"kitchen\", \"counter\", \"wall\"]','indoor','{\"price\": 1, \"luxury\": 5, \"modern\": 5, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (19,'INDIAN BLACK','หินแกรนิต ดำอินเดีย (Indian Black Granite) เหมาะสำหรับการนำไปทำเป็นท็อปเคาน์เตอร์ครัว ท็อปอ่างล้างมือ หรือส่วนอื่นๆ ที่ต้องการความแข็งแรง',1350.00,'https://media.siamtak.com/188f91209d4b-6555b34a18caf759173e834a_IDB.jpg','https://www.siamtak.com/products/indian-black','black','granite','[\"Modern\"]','[\"kitchen\", \"counter\", \"bathroom\"]','indoor','{\"price\": 4, \"luxury\": 3, \"modern\": 5, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:24:32');
INSERT INTO `granite_products` VALUES (20,'AZUL WHITE','หินแกรนิตอะซูลไวท์ (Azul White Granite) ความงดงามที่ผสมผสานระหว่างความบริสุทธิ์ของสีขาวและเส้นแร่สีฟ้าอ่อนอย่างลงตัวลวดลายที่ดูอ่อนโยนและมีมิติ สร้างบรรยากาศโปร่ง โล่ง และหรูหราในทุกพื้นที่ เหมาะกับการตกแต่งทั้งภายในและภายนอก ให้สัมผัสของความสว่างและความพิเศษเหนือใครลงตัวกับงานดีไซน์ที่ต้องการความเรียบหรู ไม่ว่าจะเป็นพื้น เคาน์เตอร์ หรือผนัง',2490.00,'https://media.siamtak.com/9a49afac0d66-67ca76a5fa98d6c769fa6b54_AZW.jpg','https://www.siamtak.com/products/azul-white','white','granite','[\"Luxury\", \"Modern\"]','[\"floor\", \"counter\", \"wall\", \"outdoor\"]','both','{\"price\": 3, \"luxury\": 5, \"modern\": 5, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:24:32');
INSERT INTO `granite_products` VALUES (21,'CHINA WHITE 602','หินแกรนิต ขาวจีน 602#2 (China White Granite 602#2) หินธรรมชาติที่สะท้อนความเรียบง่ายและสะอาดตาได้อย่างไร้ที่ติ ด้วยพื้นผิวสีขาวสว่างหรือเทาอ่อนที่สม่ำเสมอทั่วทั้งแผ่น โดดเด่นด้วยการกระจายตัวของเม็ดแร่สีดำและสีเทาขนาดเล็กอย่างสม่ำเสมอ ทำให้เกิดลวดลายที่ดูละมุนตาและเป็นระเบียบ หินชนิดนี้เป็นที่นิยมอย่างมากในงานออกแบบที่เน้นความโมเดิร์นและมินิมอล เพราะให้ความรู้สึกโปร่งโล่งสบายตา และยังเป็นวัสดุที่แข็งแกร่งทนทานต่อการขีดข่วนและความร้อนสูง จึงเหมาะอย่างยิ่งสำหรับเคาน์เตอร์ครัวและพื้นที่ที่ต้องการความสวยงามควบคู่ไปกับฟังก์ชันการใช้งาน',459.00,'https://media.siamtak.com/ee0e12b2c8cb-67ebb2308461601163452488_602-low.jpg','https://www.siamtak.com/products/china-white-602-2','white','granite','[\"Modern\", \"Minimal\"]','[\"kitchen\", \"counter\"]','indoor','{\"price\": 5, \"luxury\": 3, \"modern\": 5, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:26:24');
INSERT INTO `granite_products` VALUES (22,'KHAO TONE','หินแกรนิตเขาโทน (Khao Tone Granite) หินธรรมชาติที่ถ่ายทอดความสงบและเรียบง่ายแบบไทยได้อย่างงดงามสมชื่อ ด้วยพื้นผิวสีขาวสะอาดตาเป็นหลัก ประดับด้วยเม็ดแร่สีดำและสีเทาขนาดเล็กที่กระจายตัวอยู่ทั่วทั้งแผ่นอย่างมีศิลปะ ทำให้เกิดลวดลายที่ดูละมุนและมีมิติ ไม่จัดจ้านเกินไป หินชนิดนี้เป็นสัญลักษณ์ของความแข็งแกร่งและทนทานที่มาจากธรรมชาติอย่างแท้จริง เหมาะอย่างยิ่งสำหรับผู้ที่ต้องการสร้างบรรยากาศที่ดูโปร่งโล่ง สะอาด และคลาสสิกให้กับพื้นที่ ไม่ว่าจะเป็นเคาน์เตอร์, พื้น, หรือผนัง หินเขาโทนจะมอบความงามที่เหนือกาลเวลาได้อย่างลงตัว',1790.00,'https://media.siamtak.com/dd355981a3b0-6555b1b6a8b87ce0b60c40f5_KT.jpg','https://www.siamtak.com/products/khao-tone','white','granite','[\"Classic\", \"Minimal\"]','[\"counter\", \"floor\", \"wall\"]','indoor','{\"price\": 3, \"luxury\": 3, \"modern\": 4, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:24:32');
INSERT INTO `granite_products` VALUES (23,'ECLIPSE','หินแกรนิตอีคลิปส์ (Eclipse Granite) นำเสนอความลึกลับและความงามที่น่าค้นหา ด้วยพื้นผิวสีเทาเข้มเกือบดำที่ดูแข็งแกร่งและน่าเกรงขาม ลวดลายเส้นสีขาวและสีเทาที่กระจัดกระจายอยู่ทั่วแผ่นให้ความรู้สึกเหมือนแสงจันทร์ที่ส่องผ่านเมฆในยามค่ำคืน หินชนิดนี้เป็นตัวเลือกที่สมบูรณ์แบบสำหรับงานที่ต้องการความโดดเด่นและมีดีไซน์ที่แตกต่างอย่างมีระดับ',2990.00,'https://media.siamtak.com/f08009090a75-65447bf303300e91cc80cff4_ECL.jpeg','https://www.siamtak.com/products/eclipse','grey','granite','[\"Luxury\"]','[\"counter\", \"wall\", \"floor\"]','indoor','{\"price\": 2, \"luxury\": 5, \"modern\": 3, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:20:34');
INSERT INTO `granite_products` VALUES (24,'ANTIQUE WHITE','หินแกรนิตแอนติกไวท์ (Antique White granite) หินธรรมชาติที่ถ่ายทอดความงามแบบคลาสสิกและอบอุ่นได้อย่างลงตัว ด้วยพื้นผิวสีขาวครีมหรือขาวนวลที่ดูอ่อนโยนเป็นหลัก แต่ถูกเติมเต็มด้วยเม็ดแร่สีดำและสีเทาที่กระจายตัวอยู่ทั่วทั้งแผ่นอย่างมีเสน่ห์ จุดเด่นที่ทำให้หินชนิดนี้มีเอกลักษณ์เฉพาะตัวคือเม็ดแร่สีแดงเข้มหรือสีสนิมที่แทรกอยู่ สร้างความรู้สึกวินเทจและน่าสนใจไม่เหมือนใคร หินแอนติกไวท์จึงเหมาะสำหรับผู้ที่ต้องการสร้างบรรยากาศที่ดูหรูหราแบบย้อนยุคแต่ยังคงความแข็งแกร่งทนทานต่อการใช้งานหนักได้เป็นอย่างดี',2490.00,'https://media.siamtak.com/4fe473692ac2-659f63fa00f874b78b9d2d52_AT1.jpg','https://www.siamtak.com/products/antique-white','white','granite','[\"Classic\"]','[\"counter\", \"wall\", \"floor\"]','indoor','{\"price\": 3, \"luxury\": 3, \"modern\": 3, \"durability\": 5, \"maintenance\": 4}','2026-09-21 05:04:51','2026-10-08 09:24:32');
INSERT INTO `granite_products` VALUES (25,'DONNA GREY','หินแกรนิตดอนน่าเกรย์ (Donna Grey Granite) โทนสีเทาเข้มดูทันสมัยพร้อมลวดลายละเอียดอ่อน ทำให้ดอนน่าเกรย์เป็นหินที่เหมาะกับทุกสไตล์ให้ความรู้สึกเรียบหรูและโมเดิร์นในเวลาเดียวกัน สร้างบรรยากาศที่ดูสงบและสบายตาพื้นผิวแข็งแรงทนทาน เหมาะสำหรับทั้งพื้นที่ภายในและภายนอกอาคาร เหมาะกับงานเคาน์เตอร์ พื้น หรือผนังที่ต้องการความคงทนและดีไซน์ร่วมสมัย',1790.00,'https://media.siamtak.com/7a05bb107c9e-68021df0de7b533443eb3f38_DNG.jpg','https://www.siamtak.com/products/donna-grey','เทา','granite','[\"Modern\"]','[\"counter\", \"wall\", \"floor\", \"outdoor\"]','both','{\"price\": 4, \"luxury\": 1, \"modern\": 3, \"durability\": 4, \"maintenance\": 4}','2026-10-15 14:16:09','2026-10-15 14:22:40');
